(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["hr"] = {"ui":{"skip":"Preskoči na sadržaj","back":"← Natrag na AI-gile","lang.button":"Jezik: {name}","lang.dialog":"Odaberi jezik","lang.search":"Traži jezike","lang.none":"Nijedan jezik ne odgovara","lang.notYet":"{name} još nije preveden","theme.aria":"Prebaci između svijetle i tamne teme","theme.toLight":"Prebaci na svijetlu temu","theme.toDark":"Prebaci na tamnu temu","index.title":"AI-gile: tvoj AI razvojni tim, na jednoj ploči","index.description":"AI-gile je kanban ploča za AI timove koji programiraju. Rade dok ti spavaš; tebi ostaje jedna kratka hrpa stvari koje trebaš odlučiti, testirati i prihvatiti.","hero.logoAlt":"Ikona AI-gile ploče","hero.h1.html":"Tvoj AI razvojni tim, na jednoj&nbsp;ploči.","hero.alpha":"🐣 Zatvorena pre-alfa","hero.alphaTitle":"Rano je i nedovršeno: hvala što isprobavaš!","hero.lede":"Grade dok ti spavaš. Budiš se uz jednu kratku hrpu: nekoliko pitanja, nekoliko stvari za testiranje, jedan ili dva ljubičasta dijamanta. Klikneš, prihvatiš, vratiš se kavi.","dl.windows":"Windows aplikacija","dl.browser":"Pokreni u pregledniku","dl.soon":"Uskoro","dl.notify":"🔔 Javi mi kad se otvori","dl.notifySmall":"Alfa ili beta","hero.secondary":"Agile, ali timu ne treba stand-up kava. (Stand-up ipak održavaju.)","pitch.h2":"AI-gile u onoliko riječi koliko želiš","pitch.lede":"Odaberi duljinu, od jedne riječi do 144. Svaka duljina ima svoj opis, napisan baš za tu veličinu. Povuci klizač ili koristi strelice.","pitch.rangeLabel":"Duljina u riječima","pitch.dice":"🎲 druga verzija","pitch.words.one":"{n} riječ","pitch.words.few":"{n} riječi","pitch.words.other":"{n} riječi","pitch.letters.one":"{n} slovo","pitch.letters.few":"{n} slova","pitch.letters.other":"{n} slova","pitch.chars.one":"{n} znak","pitch.chars.few":"{n} znaka","pitch.chars.other":"{n} znakova","count.line.html.one":"{n} kartica na ploči upravo sada","count.line.html.few":"{n} kartice na ploči upravo sada","count.line.html.other":"{n} kartica na ploči upravo sada","features.aria":"Što radi","f.pile.h":"Jedna hrpa za tebe","f.pile.html":"<b>Za tebe</b> sadrži sve što čeka tebe, kroz sve projekte: pitanja, stvari za testiranje, zadatke koje može obaviti samo čovjek. Tvoj red kaže što je sljedeće i koliko traje.","f.sleep.h":"Timovi koji rade dok ti spavaš","f.sleep.p":"Svaki projekt ima lead i tim AI agenata. Komentiraj karticu i tim se budi, odradi posao i vrati je s koracima koje može pratiti i umoran čovjek.","f.tester.h":"AI tester provjerava prvi","f.tester.p":"Prije nego išta stigne do tebe, tester prati korake u kopiji aplikacije i pokazuje što je vidio, sa snimkom zaslona. Prelistaj one koje su prošle i prihvati jednim klikom.","f.proof.h":"Dokazi, ne obećanja","f.proof.p":"Svaka primopredaja pokazuje što se promijenilo: datoteke, diff, snimke zaslona. Ne moraš otvarati svaku aplikaciju da vidiš je li gotovo.","f.chat.h":"Razgovaraj sa svojim leadovima","f.chat.p":"Traka u stilu Discorda: jedna ikona po projektu, ljubičasti dijamanti za ono što treba tebe. Pošalji leadu ideju; pretvorit će je u kartice i plan, s gumbom ✅ Go.","f.tidy.h":"Sam se uredi","f.tidy.p":"Povezane kartice stapaju se u jednu, zbrkani naslovi se ispravljaju, a provjera tokena drži kod vitkim. Manje stvari između kojih se prebacuješ, manje razmišljanja.","f.private.h":"Tvoje, na tvom računalu","f.private.li1":"Ploča radi na tvom računalu i odgovara samo tebi.","f.private.li2":"Privatne poruke među ljudima šifrirane su od kraja do kraja.","f.private.li3":"Bez računa, bez tragača, bez kolačića.","f.lang.h":"Na tvom jeziku","f.lang.p":"Više od 120 jezika, od nizozemskog, velškog i japanskog do gusarskog, Yode i klingonskog, s brzim povratkom na engleski za razvojničke riječi.","tl.aria":"Vremenska crta od prvog razgovora do plana","tl.h2":"Od prvog razgovora do onoga što slijedi","tl.lede":"Pravi datumi i vremena, u tvojoj vremenskoj zoni. Nakon današnjeg dana to je plan, bez obećanih datuma.","tl.today":"Danas","tl.planned":"planirano","tl.cards.one":"{n} kartica","tl.cards.few":"{n} kartice","tl.cards.other":"{n} kartica","join.h2":"Pridruži se","join.lede":"AI-gile gradi jedan mali čovjek i velik broj strpljivih agenata. Zasad je privatan, u zatvorenoj alfi s prijateljima. Želiš li probati kad se otvori?","join.btn":"Prijavi interes","join.small":"Javit ćemo ti se e-poštom, ništa više","footer.tag":"AI-gile. Bez tragača, bez kolačića, bez stand-up kave.","footer.licence":"Poslovna licenca","footer.status":"Status","form.sending":"Šaljem…","form.failed":"Nije uspjelo: pokušaj ponovno kasnije.","form.offline":"Nije moguće doći do AI-gilea: pokušaj ponovno kasnije.","interest.title":"AI-gile: javi mi kad se alfa otvori","interest.description":"Ostavi e-adresu da saznaš kad se otvori zatvorena alfa ili beta AI-gilea.","interest.h1":"🔔 Javi mi kad se otvori","interest.lede":"AI-gile je u zatvorenoj pre-alfi. Ostavi e-adresu i javit ćemo se jednom, kad bude mjesta za tebe.","interest.email":"Tvoja e-adresa","interest.which":"Koje testiranje?","interest.alpha":"Zatvorena alfa: rano, grubo, puno promjena","interest.beta":"Beta: stabilnija, kasnije","interest.both":"Svejedno, što prije dođe","interest.submit":"Stavi me na popis","interest.thanks":"Hvala! Na popisu si.","interest.kept":"Čuvamo samo tvoju e-adresu i odabrano testiranje, samo za ovaj popis. Bez newslettera, bez tragača.","licence.title":"AI-gile: poslovna licenca","licence.description":"Koristiš AI-gile u poslu? Zatraži besplatnu poslovnu licencu.","licence.h1":"📜 Poslovna licenca","licence.lede":"Koristiš AI-gile na poslu? Reci nam tko si i čime se baviš. Ako donosi nešto dobro, licenca je besplatna.","licence.company":"Tvrtka","licence.website":"Web-stranica","licence.what":"Čime se baviš","licence.how":"Kako to pomaže svijetu","licence.email":"E-adresa","licence.submit":"Prijavi se","licence.thanks":"Hvala! Odgovorit ćemo e-poštom.","status.title":"Status AI-gilea","status.h1":"Status AI-gilea","status.quiet":"Sve je mirno","status.checking":"Provjeravam…","status.offline":"Trenutno nije moguće doći do statusne usluge (pokušavam ponovno)","status.updated":"ažurirano {ago}","status.justNow":"upravo sada","status.min":"prije {n} min","status.hours":"prije {n} h","status.days":"prije {n} d","live.h2":"Gledajte kako se gradi, uživo","live.caption":"Svaka kartica je skrivena: vidite oblik posla, a ne riječi.","live.watching.one":"uživo: {n} gleda","live.watching.other":"uživo: {n} gleda","live.offline":"Ploča uživo malo odmara. Svratite uskoro.","live.cols":"Backlog|Na redu|U tijeku|Tim provjerava|Za tvoje testiranje|Za tim|Gotovo","live.last.now":"Zadnja kartica premještena upravo sada","live.last.min.one":"Zadnja kartica premještena prije {n} min","live.last.min.other":"Zadnja kartica premještena prije {n} min","live.last.hour.one":"Zadnja kartica premještena prije {n} sat","live.last.hour.other":"Zadnja kartica premještena prije {n} sati","live.last.day.one":"Zadnja kartica premještena prije {n} dan","live.last.day.other":"Zadnja kartica premještena prije {n} dana"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Roboti.","Delegirano."]},{"n":2,"texts":["Kanban robota.","Agenti, posloženi.","Ideje, izgrađene."]},{"n":3,"texts":["Kanban za robote.","Ideje postaju značajke.","Besplatni agentski kanban."]},{"n":5,"texts":["Kanban ploča koju vode agenti.","Ti pišeš kartice. Agenti grade.","Besplatno, lokalno, testirano, pomalo ludo."]},{"n":8,"texts":["Besplatna kanban ploča na kojoj rade AI agenti.","Napiši ideju. Agenti je grade. Ti prihvaćaš.","Agile za jednog čovjeka i mnogo strpljivih robota."]},{"n":13,"texts":["Kanban ploča na tvom računalu, a kartice preuzimaju AI agenti i rade ih.","Napiši ideju. Tim agenata je izgradi. Tester je provjeri prije tebe.","Besplatno, bez računa, bez tragača: ploča, nekoliko robota i ti kao šef."]},{"n":21,"texts":["AI-gile je kanban ploča za rad s AI agentima koji programiraju. Oni preuzimaju kartice; ti ih testiraš i prihvaćaš.","Svaki projekt dobiva lead i tim AI agenata. Komentiraj bilo koju karticu i tim odmah kreće raditi.","Besplatna osobna ploča zadataka koja radi na tvom računalu. Radnici su roboti. Onaj koji kaže da si ti."]},{"n":34,"texts":["Ideje stavljaš na ploču. Tim AI agenata pretvara ih u značajke koje rade, testira ih i vraća ti ih s koracima za isprobavanje. Ništa ne vrijedi kao gotovo dok ti to ne kažeš.","AI-gile je domaća kanban ploča koju je Rich izgradio uz mnogo pomoći agenata kojima sada upravlja. Besplatna je, radi na tvom računalu i dijeli se s prijateljima, ne prodaje se.","Zamisli običnu kanban ploču sa stupcima od Backloga do Gotovo, samo što kartice preuzimaju AI agenti. Javljaju napredak, pitaju kad zapnu i uvijek čekaju tvoj palac gore."]},{"n":55,"texts":["AI-gile je kanban ploča na kojoj je tim sastavljen od AI agenata. Svaki projekt ima lead koji planira posao i pomoćnike koji ga grade. Kad je značajka gotova, AI tester je isproba i snimi zaslon, a zatim stiže na tvoju hrpu. Prihvati je ili komentiraj pa je prerade.","Počelo je kao jedan način da jedna osoba prati mnogo AI programerskih sesija odjednom, a preraslo je u pravu ploču. Radi na tvom računalu, ne traži račun i nema tragača. Besplatna je za prijatelje i svakoga tko je znatiželjan. Također je nedovršena, pa očekuj grube rubove i poneko iznenađenje.","Evo poštene verzije, bez uljepšavanja. I dalje ti moraš imati ideje i provjeravati rezultate. AI-gile radi sve između: drži kartice u redu, budi pravog agenta kad komentiraš, pokazuje točno što se promijenilo, tko je to napravio i sve to drži na jednoj kratkoj hrpi za tebe."]},{"n":89,"texts":["AI-gile je besplatna kanban ploča koju pokrećeš na vlastitom računalu. Umjesto ljudi, svaki projekt ima tim AI agenata: lead koji tvoje ideje pretvara u kartice i plan te pomoćnike koji preuzimaju kartice po prioritetu. Kad je nešto izgrađeno, AI tester prati korake testiranja i pokazuje ti što je vidio. Zatim sve čeka na jednoj hrpi nazvanoj Za tebe. Prihvatiš to ili komentiraš pa tim pokuša ponovno. Ništa ne stiže u Gotovo bez tebe.","Nekoliko stvari koje možda ne očekuješ. Noćni čuvar dopunjuje stupac Na redu dok ti spavaš, birajući kartice kojima ne treba tvoj odgovor. Brojač tokena pokazuje koliko su agenti potrošili danas i ovaj tjedan, a način bez tokena kaže im da prestanu trošiti. Možeš slati poruke prijateljima, a privatne poruke šifrirane su od kraja do kraja. Ploča govori oko 120 jezika, uključujući nizozemski, flamanski, gusarski i klingonski. Sve je besplatno, a nitko ti to ne pokušava ni prodati.","AI-gile je mali osobni projekt, a ne tvrtka. Rich je želio brinuti o nekoliko AI projekata bez otvaranja svake aplikacije da provjeri stanje, pa su on i agenti izgradili ploču za to, a zatim su tu ploču koristili za gradnju ostatka sebe. U zatvorenoj je pre-alfi, što znači da radi, uglavnom, za šačicu prijatelja. Nema stranice s cijenama, nema newslettera i nema plana rasta. Ako ti zvuči korisno, možeš se javiti da probaš kad se malo više otvori."]},{"n":144,"texts":["AI-gile je kanban ploča za jednog čovjeka i mnogo AI agenata. Radi na tvom računalu i potpuno je besplatna, bez računa i bez ikakvih tragača, a tvoji podaci ostaju kod tebe. Dodaješ projekte, a svaki projekt dobiva lead i mali tim. S leadom razgovaraš, pomalo kao na Discordu, i opišeš ideju; lead je pretvara u kartice i plan, pa čeka da pritisneš Go. Tim prolazi kroz kartice po prioritetu, koristeći jednostavnu naredbenu liniju napravljenu za jezične modele. Prije nego išta stigne natrag do tebe, AI tester prati korake u kopiji aplikacije i prilaže snimku zaslona. Gotov posao stiže na tvoju hrpu s promijenjenim datotekama i diffom. Prihvatiš ga ili ostaviš komentar, pa se tim probudi i pokuša ponovno. Samo ti možeš premjestiti karticu u Gotovo.","Otprilike ovako izgleda dan s AI-gileom. Navečer ostaviš nekoliko komentara: ovaj je gumb na krivom mjestu, taj popis treba sortirati, može li tamna tema. Odeš spavati. Agenti pročitaju komentare, naprave izmjene, testiraju ih i vrate ti ih. Ako stupac Na redu presuši, noćni čuvar ga puni iz backloga karticama kojima ne treba tvoj odgovor. Ujutro te čeka jedna kratka hrpa: par pitanja i nekoliko stvari za isprobati, svaka s koracima koje može pratiti pospana osoba i snimkom zaslona na kojoj radi. Pregledaš ih klikom, prihvatiš dobre, a ostale vratiš. Brojač tokena pokazuje koliko je sve to potrošilo, a način bez tokena tu je za štedljive tjedne. Zatim doručkuješ, a u tome ti agenti još ne mogu pomoći.","Prvo, što AI-gile nije. Nije startup, nije na prodaju i nitko ne prikuplja tvoje podatke. To je besplatna ploča koja radi na tvom računalu, bez računa, bez tragača i bez kolačića. Što jest: jedno uredno mjesto na kojem vidiš sve AI programerske projekte odjednom, s timom agenata koji rade kartice i tobom koji donosiš odluke. Spaja povezane kartice, ispravlja zbrkane naslove i pazi koliko kod ostaje vitak. Govori oko 120 jezika, od nizozemskog i flamanskog do gusarskog i klingonskog. Prijatelji mogu slati poruke jedni drugima, privatno i šifrirano. Izgradili su ga Rich i velik broj strpljivih agenata, uglavnom koristeći sam program. U zatvorenoj je pre-alfi, pa je mjestimice grub. Ako ti zvuči zabavno, lijepo zamoli i možda uđeš rano."]}],"quips":{"1":"Jedna riječ. Hrabro. Možda i previše hrabro.","3":"Tri riječi. Već iskrenije od većine stranica proizvoda.","8":"Osam riječi. I dalje kraće od stand-upa.","21":"Duljine su, usput, story pointovi. Naravno da jesu.","55":"Pedeset i pet riječi. Dok si čitao, dvije su kartice završene.","144":"To je ona duga. Nema 233. Agenti su otišli spavati."}},"timeline":{"first-idea.name":"Prva ideja","first-idea.line":"Sasvim prvi razgovor, prije nego što je postojao ijedan redak koda.","first-board.name":"Prva ploča","first-board.line":"Ploča koja prati vlastitu izgradnju: kartice, stupci, povuci i ispusti, projekti.","team-roles.name":"Tim i uloge","team-roles.line":"Profili agenata, predlošci timova, prostori i tko što radi.","install.name":"Instalacija i izdanja","install.line":"Zip koji prijatelj može instalirati, samoažuriranje, kanali i vraćanje unatrag.","usage-saver.name":"Štednja potrošnje","usage-saver.line":"Mjeri što pokretanja koštaju, drži kod vitkim, štedi svoj limit.","friends.name":"Prijatelji i dijeljenje","friends.line":"Privatne poruke, pomiješani relej, pozivnice, uloge i zajednički projekti.","languages.name":"Jezici","languages.line":"Svaki tekst na zaslonu u jezičnoj datoteci, prvo nizozemski i flamanski.","ai-tester.name":"AI tester","ai-tester.line":"Tester prvi provjerava svaku primopredaju i pokazuje što je vidio.","website.name":"Web-stranica","website.line":"aigile.lol, teaser i ova vremenska crta.","streaming.name":"Chat i streaming","streaming.line":"Discord, Twitch, OBS, streamerski način, GIF-ovi i emojiji.","no-ai.name":"Izdanje bez AI-ja","no-ai.line":"Ploča za ljude koji programiraju bez AI-ja i javne ploče.","night-watch.name":"Noćni čuvar","night-watch.line":"Čuvar i Scrum Master drže timove na zadatku dok ti spavaš.","p-more.name":"Sve ostalo","p-more.line":"Manje ideje koje još čekaju svoj red.","p-android.name":"Mobitel i Android","p-android.line":"Dođi do ploče s mobitela, a zatim prava Android aplikacija.","p-release.name":"Alfa i dalje","p-release.line":"Zatvorena alfa, stranica uživo, zatim beta.","p-languages.name":"Još jezika","p-languages.line":"Više od sto jezika i način uranjanja za one koji uče.","p-engines.name":"Još AI motora","p-engines.line":"Odaberi Claude, Codex ili Gemini za svakog agenta.","p-pro.name":"Profesionalna praksa","p-pro.line":"Oznake rizika, merge vrata, kartice incidenata i zaštitne ograde.","p-self.name":"Briga o tebi","p-self.line":"Način za umorne, podsjetnici za brigu o sebi i 4:20.","p-servers.name":"Poslužitelji i rast","p-servers.line":"Globalne postavke poslužitelja, uloge i planiranje rasta.","p-livestream.name":"Streaming dodaci","p-livestream.line":"Twitch chat, vlastiti emojiji i javni prikaz uživo."}};
